23	/**
24	 * Reassembles incremental A2A streaming updates into a coherent result.
25	 * Shows sequential status/messages followed by all reassembled artifacts.
26	 */
27	export class A2AResultReassembler {
28	  private messageLog: string[] = [];
29	  private artifacts = new Map<string, Artifact>();
30	  private artifactChunks = new Map<string, string[]>();
31	
32	  /**
33	   * Processes a new chunk from the A2A stream.
34	   */
35	  update(chunk: SendMessageResult) {
36	    if (!('kind' in chunk)) return;
37	
38	    switch (chunk.kind) {
39	      case 'status-update':
40	        this.appendStateInstructions(chunk.status?.state);
41	        this.pushMessage(chunk.status?.message);
42	        break;
43	
44	      case 'artifact-update':
45	        if (chunk.artifact) {
46	          const id = chunk.artifact.artifactId;
47	          const existing = this.artifacts.get(id);
48	
49	          if (chunk.append && existing) {
50	            for (const part of chunk.artifact.parts) {
51	              existing.parts.push(structuredClone(part));
52	            }
53	          } else {
54	            this.artifacts.set(id, structuredClone(chunk.artifact));
55	          }
56	
57	          const newText = extractPartsText(chunk.artifact.parts, '');
58	          let chunks = this.artifactChunks.get(id);
59	          if (!chunks) {
60	            chunks = [];
61	            this.artifactChunks.set(id, chunks);
62	          }
63	          if (chunk.append) {
64	            chunks.push(newText);
65	          } else {
66	            chunks.length = 0;
67	            chunks.push(newText);
68	          }
69	        }
70	        break;
71	
72	      case 'task':
73	        this.appendStateInstructions(chunk.status?.state);
74	        this.pushMessage(chunk.status?.message);
75	        if (chunk.artifacts) {
76	          for (const art of chunk.artifacts) {
77	            this.artifacts.set(art.artifactId, structuredClone(art));
78	            this.artifactChunks.set(art.artifactId, [
79	              extractPartsText(art.parts, ''),
80	            ]);
81	          }
82	        }
83	        // History Fallback: Some agent implementations do not populate the
84	        // status.message in their final terminal response, instead archiving
85	        // the final answer in the task's history array. To ensure we don't
86	        // present an empty result, we fallback to the most recent agent message
87	        // in the history only when the task is terminal and no other content
88	        // (message log or artifacts) has been reassembled.
89	        if (
90	          isTerminalState(chunk.status?.state) &&
91	          this.messageLog.length === 0 &&
92	          this.artifacts.size === 0 &&
93	          chunk.history &&
94	          chunk.history.length > 0
95	        ) {
96	          const lastAgentMsg = [...chunk.history]
97	            .reverse()
98	            .find((m) => m.role?.toLowerCase().includes('agent'));
99	          if (lastAgentMsg) {
100	            this.pushMessage(lastAgentMsg);
101	          }
102	        }
103	        break;
104	
105	      case 'message':
106	        this.pushMessage(chunk);
107	        break;
108	      default:
109	        // Handle unknown kinds gracefully
110	        break;
111	    }
112	  }
113	
114	  private appendStateInstructions(state: TaskState | undefined) {
115	    if (state !== 'auth-required') {
116	      return;
117	    }
118	
119	    // Prevent duplicate instructions if multiple chunks report auth-required
120	    if (!this.messageLog.includes(AUTH_REQUIRED_MSG)) {
121	      this.messageLog.push(AUTH_REQUIRED_MSG);
122	    }
123	  }
124	
125	  private pushMessage(message: Message | undefined) {
126	    if (!message) return;
127	    const text = extractPartsText(message.parts, '');
128	    if (text && this.messageLog[this.messageLog.length - 1] !== text) {
129	      this.messageLog.push(text);
130	    }
131	  }
132	
133	  /**
134	   * Returns an array of activity items representing the current reassembled state.
135	   */
136	  toActivityItems(): SubagentActivityItem[] {
137	    const isAuthRequired = this.messageLog.includes(AUTH_REQUIRED_MSG);
138	    return [
139	      isAuthRequired
140	        ? {
141	            id: 'auth-required',
142	            type: 'thought',
143	            content: AUTH_REQUIRED_MSG,
144	            status: 'running',
145	          }
146	        : {
147	            id: 'pending',
148	            type: 'thought',
149	            content: 'Working...',
150	            status: 'running',
151	          },
152	    ];
153	  }
154	
155	  /**
156	   * Returns a human-readable string representation of the current reassembled state.
157	   */
158	  toString(): string {
159	    const joinedMessages = this.messageLog.join('');
160	
161	    const artifactsOutput = Array.from(this.artifacts.keys())
162	      .map((id) => {
163	        const chunks = this.artifactChunks.get(id);
164	        const artifact = this.artifacts.get(id);
165	        if (!chunks || !artifact) return '';
166	        const content = chunks.join('');
167	        const header = artifact.name
168	          ? `Artifact (${artifact.name}):`
169	          : 'Artifact:';
170	        return `${header}\n${content}`;
171	      })
172	      .filter(Boolean)
173	      .join('\n\n');
174	
175	    if (joinedMessages && artifactsOutput) {
176	      return `${joinedMessages}\n\n${artifactsOutput}`;
177	    }
178	    return joinedMessages || artifactsOutput;
179	  }
180	}
181	
182	/**
183	 * Extracts a human-readable text representation from a Message object.
184	 * Handles Text, Data (JSON), and File parts.
185	 */
186	export function extractMessageText(message: Message | undefined): string {
187	  if (!message || !message.parts || !Array.isArray(message.parts)) {
188	    return '';
189	  }
190	
191	  return extractPartsText(message.parts, '\n');
192	}
193	
194	/**
195	 * Extracts text from an array of parts, joining them with the specified separator.
196	 */
197	function extractPartsText(
198	  parts: Part[] | undefined,
199	  separator: string,
200	): string {
201	  if (!parts || parts.length === 0) {
202	    return '';
203	  }
204	  return parts
205	    .map((p) => extractPartText(p))
206	    .filter(Boolean)
207	    .join(separator);
208	}
209	
210	/**
211	 * Extracts text from a single Part.
212	 */
213	function extractPartText(part: Part): string {
214	  if (isTextPart(part)) {
215	    return part.text;
216	  }
217	
218	  if (isDataPart(part)) {
219	    return `Data: ${JSON.stringify(part.data)}`;
220	  }
221	
222	  if (isFilePart(part)) {
223	    const fileData = part.file;
224	    if (fileData.name) {
225	      return `File: ${fileData.name}`;
226	    }
227	    if ('uri' in fileData && fileData.uri) {
228	      return `File: ${fileData.uri}`;
229	    }
230	    return `File: [binary/unnamed]`;
231	  }
232	
233	  return '';
234	}
